// Package httpapi implements the HTTP API defined in api/openapi.yaml.
// openapi.gen.go is generated by `pnpm gen`; this package supplies the handlers and middleware.
// Handlers stay thin: the rules live in internal/daily, internal/auth and internal/leaderboard.
package httpapi

import (
	"context"
	"log/slog"
	"net/http"
	"net/netip"
	"net/url"
	"time"

	"github.com/Bernabass/chess-detective/services/api/internal/auth"
	"github.com/Bernabass/chess-detective/services/api/internal/clock"
	"github.com/Bernabass/chess-detective/services/api/internal/daily"
	"github.com/Bernabass/chess-detective/services/api/internal/leaderboard"
	"github.com/Bernabass/chess-detective/services/api/internal/ratelimit"
)

// Pinger checks that the database answers.
type Pinger interface {
	Ping(ctx context.Context) error
}

// Limits are the rate limiters (SPEC §10.6), injected so tests can control them.
type Limits struct {
	AuthPerIP       *ratelimit.Limiter // login/register per client IP
	AuthPerUsername *ratelimit.Limiter // login/register per username
	PlayPerPlayer   *ratelimit.Limiter // guesses and hints per player
	StartPerIP      *ratelimit.Limiter // POST /daily/{number}/start per client IP
}

// DefaultLimits are the production limits: 10/min for auth (per IP and per username), 30/min
// for guesses and hints per player, 300/hour for starting puzzles per IP (generous: many users
// share an IP behind carrier NAT or a campus network). scale multiplies them all
// (RATE_LIMIT_SCALE: 1 in production, raised for the e2e tests).
func DefaultLimits(c clock.Clock, scale int) Limits {
	return Limits{
		AuthPerIP:       ratelimit.New(c, 10*scale, time.Minute),
		AuthPerUsername: ratelimit.New(c, 10*scale, time.Minute),
		PlayPerPlayer:   ratelimit.New(c, 30*scale, time.Minute),
		StartPerIP:      ratelimit.New(c, 300*scale, time.Hour),
	}
}

// Options are the handler's dependencies. Only Logger and DB are needed for /api/health;
// the rest of the API needs the services too.
type Options struct {
	Logger *slog.Logger
	DB     Pinger
	// HealthTimeout bounds the database ping in GET /api/health. Defaults to 2 seconds.
	HealthTimeout time.Duration

	Clock          clock.Clock
	Auth           *auth.Service
	Daily          *daily.Service
	Leaderboard    *leaderboard.Service
	Limits         Limits
	BaseURL        *url.URL
	CookieSecure   bool
	TrustedProxies []netip.Prefix
}

// Server implements the generated StrictServerInterface.
type Server struct {
	logger         *slog.Logger
	db             Pinger
	healthTimeout  time.Duration
	clock          clock.Clock
	auth           *auth.Service
	daily          *daily.Service
	board          *leaderboard.Service
	limits         Limits
	cookieSecure   bool
	trustedProxies []netip.Prefix
}

var _ StrictServerInterface = (*Server)(nil)

// NewHandler builds the complete /api handler with middleware.
func NewHandler(opts Options) http.Handler {
	if opts.HealthTimeout == 0 {
		opts.HealthTimeout = 2 * time.Second
	}
	if opts.Clock == nil {
		opts.Clock = clock.Real{}
	}
	if opts.BaseURL == nil {
		opts.BaseURL = &url.URL{Scheme: "http", Host: "localhost:5173"}
	}
	opts.Logger = withRequestIDLogging(opts.Logger)
	srv := &Server{
		logger:         opts.Logger,
		db:             opts.DB,
		healthTimeout:  opts.HealthTimeout,
		clock:          opts.Clock,
		auth:           opts.Auth,
		daily:          opts.Daily,
		board:          opts.Leaderboard,
		limits:         opts.Limits,
		cookieSecure:   opts.CookieSecure,
		trustedProxies: opts.TrustedProxies,
	}

	validator, err := newRequestValidator()
	if err != nil {
		panic(err) // the embedded spec is generated from api/openapi.yaml; failing here is a build bug
	}

	mux := http.NewServeMux()
	strict := NewStrictHandlerWithOptions(srv, nil, StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			opts.Logger.InfoContext(r.Context(), "bad request", "err", err)
			writeProblem(w, http.StatusBadRequest, "The request is invalid.")
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			writeError(opts.Logger, w, r, err)
		},
	})
	HandlerWithOptions(strict, StdHTTPServerOptions{
		BaseURL:    "/api",
		BaseRouter: mux,
		// Per matched route, so unknown paths and methods keep ServeMux's 404 and 405. The last
		// middleware runs first: the CSRF check, then the contract validator.
		Middlewares: []MiddlewareFunc{validator, func(next http.Handler) http.Handler {
			return withCSRFCheck(opts.BaseURL, next)
		}},
		ErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			opts.Logger.InfoContext(r.Context(), "bad request parameters", "err", err)
			writeProblem(w, http.StatusBadRequest, "The request parameters are invalid.")
		},
	})

	h := withProblemFallback(mux)
	h = srv.withSession(h)
	h = withBodyLimit(h)
	h = withSecurityHeaders(h)
	return withRequestID(withLogging(opts.Logger, withRecover(opts.Logger, h)))
}

// GetHealth reports whether the API is up and the database answers within the timeout.
func (s *Server) GetHealth(ctx context.Context, _ GetHealthRequestObject) (GetHealthResponseObject, error) {
	ctx, cancel := context.WithTimeout(ctx, s.healthTimeout)
	defer cancel()
	if err := s.db.Ping(ctx); err != nil {
		s.logger.WarnContext(ctx, "health check: database unavailable", "err", err)
		return GetHealth503JSONResponse{Status: HealthStatusUnavailable, Db: HealthDbError}, nil
	}
	return GetHealth200JSONResponse{Status: HealthStatusOk, Db: HealthDbOk}, nil
}

// limit takes one event from a limiter (nil limiters allow everything).
func limit(l *ratelimit.Limiter, key string) error {
	if l == nil {
		return nil
	}
	if ok, wait := l.Allow(key); !ok {
		return &tooManyRequests{retryAfter: wait}
	}
	return nil
}
